-- Ogni POI importato si lega al sentiero più vicino entro 50 m (se c'è)
UPDATE pois p SET trail_id = (SELECT t.id FROM trails t WHERE ST_DWithin(t.path::geography, p.location::geography, 50) ORDER BY ST_Distance(t.path::geography, p.location::geography) LIMIT 1) WHERE p.trail_id IS NULL;
